import Footer from '../components/Footer';

function Preferences() {
    return (
        <div className="home">
            <Header />
            <div className="my-container">
                    <h2>Préférences</h2>
                <p>Cette page est en construction.</p>
            </div>
            <Footer />
        </div>
    );
}
export default Preferences;
